#![forbid(unsafe_code)]

//! M9.8dm differential harness: the autoindexing inference service.
//!
//! Runs every case in `tests/fixtures/m98dm_cases.json` (generated by the Go
//! baseline harness
//! `internal/codeintel/autoindexing/internal/inference/zz_m98dm_harness_test.go`)
//! through [`InferenceService`] with a fake git service, and prints one
//! canonical `luic` JSON line per case:
//!
//! ```text
//! {"case":…,"ok":true,"jobs":[…],"logs":…}
//! {"case":…,"ok":false,"err":"limit|syntax|module-not-found|runtime"}
//! ```
//!
//! Jobs are sorted by their canonical JSON because the Go baseline iterates a
//! map of recognizers; print timestamps are normalised to `[<ts>]`. The
//! diff script (`test_ws/p9-go/run_codeintel_autoindexing_inference_diff.sh`)
//! compares this output with the Go harness's.

use std::collections::BTreeMap;
use std::sync::Arc;

use async_trait::async_trait;
use serde::Deserialize;

use sg_luasandbox::Service as LuaSandboxService;
use sg_service_worker::jobs::autoindex_config::{AutoIndexJobSpec, DockerStep};
use sg_service_worker::jobs::codeintel_autoindexing_inference::{
    ArchiveOptions, DirEntry, GitService, InferenceError, InferenceService, InferenceSettings,
    RateLimiter, SandboxService,
};

/// One differential case, mirroring `m98dmCase` in the Go harness.
#[derive(Debug, Deserialize)]
struct Case {
    name: String,
    #[serde(default)]
    files: BTreeMap<String, String>,
    #[serde(default, rename = "override")]
    override_script: String,
    #[serde(default)]
    max_files: usize,
    #[serde(default)]
    max_size: i64,
}

/// Fake `GitService`: `ReadDir` lists sorted paths, `Archive` builds an
/// in-memory tar with the same regular-file headers as
/// `unpacktest.CreateTarArchive`. The baseline resolves the empty commit.
struct FakeGit {
    paths: Vec<String>,
    files: BTreeMap<String, String>,
}

#[async_trait]
impl GitService for FakeGit {
    async fn resolve_revision(&self, _repo: &str, _spec: &str) -> Result<String, String> {
        Ok(String::new())
    }

    async fn read_dir(
        &self,
        _repo: &str,
        _commit: &str,
        _path: &str,
        _recurse: bool,
    ) -> Result<Vec<DirEntry>, String> {
        Ok(self
            .paths
            .iter()
            .map(|name| DirEntry {
                name: name.clone(),
                is_dir: false,
            })
            .collect())
    }

    async fn archive(&self, _repo: &str, options: ArchiveOptions) -> Result<Vec<u8>, String> {
        let mut builder = tar::Builder::new(Vec::new());
        for path in &options.paths {
            let contents = self.files.get(path).cloned().unwrap_or_default();
            let mut header = tar::Header::new_gnu();
            header.set_size(contents.len() as u64);
            header.set_mode(0o644);
            builder
                .append_data(&mut header, path, contents.as_bytes())
                .map_err(|error| error.to_string())?;
        }
        builder.into_inner().map_err(|error| error.to_string())
    }
}

/// Fake `ratelimit.InstrumentedLimiter`: the baseline test uses a 100/s
/// limiter; there is nothing to wait for at that rate.
struct NoopLimiter;

#[async_trait]
impl RateLimiter for NoopLimiter {
    async fn wait(&self) -> Result<(), String> {
        Ok(())
    }
}

/// `serde_json`-compatible string literal (no HTML escaping), matching the Go
/// harness's `SetEscapeHTML(false)` encoder.
fn quote(value: &str) -> String {
    serde_json::to_string(value).expect("string encoding")
}

fn strings(values: Option<&Vec<String>>) -> String {
    let values = values.map(Vec::as_slice).unwrap_or_default();
    format!(
        "[{}]",
        values
            .iter()
            .map(|value| quote(value))
            .collect::<Vec<_>>()
            .join(",")
    )
}

fn steps(steps: Option<&Vec<DockerStep>>) -> String {
    let steps = steps.map(Vec::as_slice).unwrap_or_default();
    let rendered: Vec<String> = steps
        .iter()
        .map(|step| {
            format!(
                r#"{{"root":{},"image":{},"commands":{}}}"#,
                quote(&step.root),
                quote(&step.image),
                strings(step.commands.as_ref()),
            )
        })
        .collect();
    format!("[{}]", rendered.join(","))
}

fn job_json(job: &AutoIndexJobSpec) -> String {
    format!(
        r#"{{"steps":{},"local_steps":{},"root":{},"indexer":{},"indexer_args":{},"outfile":{},"requested_envvars":{}}}"#,
        steps(job.steps.as_ref()),
        strings(job.local_steps.as_ref()),
        quote(&job.root),
        quote(&job.indexer),
        strings(job.indexer_args.as_ref()),
        quote(&job.outfile),
        strings(job.requested_env_vars.as_ref()),
    )
}

/// The Go harness's `m98dmClassify` over the Rust error shape.
fn classify(error: &InferenceError) -> &'static str {
    match error {
        InferenceError::Limit(_) => "limit",
        InferenceError::Other(message) => {
            if message.contains("syntax error") {
                "syntax"
            } else if message.contains("not found") {
                "module-not-found"
            } else {
                "runtime"
            }
        }
    }
}

/// Replace `[<RFC3339 timestamp>]` with `[<ts>]`, like the Go harness.
fn normalize_timestamps(logs: &str) -> String {
    let mut out = String::with_capacity(logs.len());
    let mut rest = logs;
    while let Some(start) = rest.find('[') {
        let Some(relative_end) = rest[start..].find(']') else {
            break;
        };
        let end = start + relative_end;
        out.push_str(&rest[..start]);
        let inner = &rest[start + 1..end];
        if inner.contains('T') && inner.ends_with('Z') {
            out.push_str("[<ts>]");
        } else {
            out.push_str(&rest[start..=end]);
        }
        rest = &rest[end + 1..];
    }
    out.push_str(rest);
    out
}

fn emit_ok(case: &str, jobs: &[AutoIndexJobSpec], logs: &str) {
    let mut rendered: Vec<String> = jobs.iter().map(job_json).collect();
    rendered.sort();
    let mut line = format!(
        r#"{{"case":{},"ok":true,"jobs":[{}]"#,
        quote(case),
        rendered.join(",")
    );
    if !logs.is_empty() {
        line.push_str(&format!(r#","logs":{}"#, quote(logs)));
    }
    line.push('}');
    println!("{line}");
}

fn emit_error(case: &str, class: &str) {
    println!(
        r#"{{"case":{},"ok":false,"err":{}}}"#,
        quote(case),
        quote(class)
    );
}

async fn run_case(case: &Case, sandbox_service: Arc<dyn SandboxService>) {
    let mut paths: Vec<String> = case.files.keys().cloned().collect();
    paths.sort();

    let git_service = FakeGit {
        paths,
        files: case.files.clone(),
    };

    let settings = InferenceSettings {
        indexer_overrides: BTreeMap::new(),
        maximum_files_with_content_count: if case.max_files == 0 {
            100
        } else {
            case.max_files
        },
        maximum_file_with_content_size_bytes: if case.max_size == 0 {
            1024 * 1024
        } else {
            case.max_size
        },
    };

    let service = InferenceService::new(
        sandbox_service,
        Arc::new(git_service),
        Arc::new(NoopLimiter),
        settings,
    );

    match service
        .infer_index_jobs("github.com/test/test", "HEAD", &case.override_script)
        .await
    {
        Ok(result) => emit_ok(
            &case.name,
            &result.index_jobs,
            &normalize_timestamps(&result.inference_output),
        ),
        Err(error) => emit_error(&case.name, classify(&error)),
    }
}

/// The differential body. It prints the `luic` lines consumed by
/// `run_codeintel_autoindexing_inference_diff.sh`; the Go harness prints the
/// same lines and the script diffs them.
#[tokio::test]
async fn emits_go_comparison_lines() {
    let cases: Vec<Case> =
        serde_json::from_str(include_str!("fixtures/m98dm_cases.json")).expect("cases fixture");

    let sandbox_service: Arc<dyn SandboxService> = Arc::new(LuaSandboxService::new());
    for case in &cases {
        run_case(case, sandbox_service.clone()).await;
    }
}
